/* Diva Desk - keyboard, focus and workflow layer (DEC-85 to DEC-100).
 *
 * Loaded through `app_include_js` by the `diva_desk` app. Everything that
 * touches permissions, money, stock or payments lives on the server in
 * `diva_guard.desk_api`; this file only moves the cursor and opens dialogs.
 *
 * Item             : the Item list "Add" opens the Diva item dialog (item +
 *                    opening stock reconciliation); a blank barcode is
 *                    generated by the server. Enter on Opening Stock, Selling
 *                    Price or UOM moves to a safe field, never the image upload.
 * Purchase Receipt : supplier -> accepted warehouse -> item row (inline, no
 *                    row editor), Add New Item (creates the item, adds the line),
 *                    Print after submit. Save/Submit use the ERPNext defaults.
 * Purchase Invoice
 * Sales Invoice    : Add New Item on drafts; Pay (full or partial, Cash) and
 *                    Print + a Share dropdown on submitted invoices.
 * Shortcuts        : F1 help, F2 party, F3 item, F8 pay, F9 print,
 *                    Ctrl+S save, Ctrl+Enter submit.
 * Search           : the Desk search bar (Ctrl+K) is extended by the
 *                    `awesomebar_search` hook in diva_guard.
 */
(function () {
	"use strict";

	const DEFAULT_WAREHOUSE = "Stores - DD";
	const DEFAULT_PAYMENT_MODE = "Cash";
	const INVOICE_PRINT_FORMAT = "Diva Sales Invoice A4";
	const PURCHASE_INVOICE_PRINT_FORMAT = "Diva Purchase Invoice A4";
	const PAYMENT_RECEIPT_PRINT_FORMAT = "Diva Payment Receipt";
	const RECEIPT_PRINT_FORMAT = "Diva Purchase Receipt A4";
	const PCS_PER_DOZEN = 12;

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------
	function money(value) {
		return format_currency(flt(value), frappe.defaults.get_default("currency") || "EGP");
	}

	function is_new(frm) {
		return Boolean(frm && frm.doc && frm.doc.__islocal);
	}

	function is_draft(frm) {
		return Boolean(frm && frm.doc && frm.doc.docstatus === 0);
	}

	function is_submitted(frm) {
		return Boolean(frm && frm.doc && frm.doc.docstatus === 1);
	}

	function focus_field(frm, fieldname) {
		const field = frm && frm.fields_dict && frm.fields_dict[fieldname];
		if (!field) return;
		setTimeout(() => {
			if (typeof field.set_focus === "function") {
				field.set_focus();
			} else if (field.$input && field.$input.length) {
				field.$input.trigger("focus");
			}
			const input = field.$input && field.$input.get(0);
			if (input && input.select) input.select();
		}, 150);
	}

	// Focus the item-code cell inline. The full row editor opens only from the
	// pin/expand icon, never from Tab (DEC-90). Clicking the grid cell turns it
	// into an inline input; Tab then moves to the next cell.
	function focus_item_row(frm) {
		const items = frm && frm.fields_dict && frm.fields_dict.items;
		const grid = items && items.grid;
		if (!grid) return;
		if (!(grid.grid_rows || []).length) {
			// show=false: add the row without opening the full row editor.
			grid.add_new_row(null, null, false, null, false);
		}
		setTimeout(() => {
			const $cell = grid.wrapper.find(".grid-row").last().find('[data-fieldname="item_code"]').first();
			if (!$cell.length) return;
			const cell = $cell.get(0);
			if (cell.scrollIntoView) cell.scrollIntoView({ block: "nearest" });
			cell.click();
			const input = $cell.find("input").get(0);
			if (input) {
				input.focus();
				if (input.select) input.select();
			}
		}, 300);
	}

	function open_print(doctype, name, printFormat, trigger) {
		const params = new URLSearchParams({
			doctype: doctype,
			name: name,
			format: printFormat,
			no_letterhead: "1",
		});
		if (trigger) params.set("trigger_print", "1");
		window.open("/printview?" + params.toString(), "_blank");
	}

	function open_whatsapp(frm) {
		frappe
			.xcall("diva_guard.share.invoice_share", {
				doctype: frm.doctype,
				name: frm.doc.name,
				language: frappe.boot && frappe.boot.lang === "en" ? "en" : "ar",
			})
			.then((result) => window.open(result.wa_link, "_blank"))
			.catch((error) => {
				frappe.msgprint({
					title: __("Open in WhatsApp failed"),
					message: (error && (error.message || error._server_messages)) || String(error),
					indicator: "red",
				});
			});
	}

	// Print stays a one-click button; Download PDF and Open in WhatsApp live in
	// one Share dropdown (DEC-97 amendment).
	function add_share_buttons(frm, printFormat) {
		frm.add_custom_button(__("Print"), () =>
			open_print(frm.doctype, frm.doc.name, printFormat)
		);
		frm.add_custom_button(
			__("Download PDF"),
			() => open_print(frm.doctype, frm.doc.name, printFormat, true),
			__("Share")
		);
		frm.add_custom_button(__("Open in WhatsApp"), () => open_whatsapp(frm), __("Share"));
	}

	function fieldname_of(element) {
		const control = $(element).closest("[data-fieldname]");
		return control.length ? control.attr("data-fieldname") : null;
	}

	// ------------------------------------------------------------------
	// EAN-13 label (drawn locally, no barcode service)
	// ------------------------------------------------------------------
	const EAN_L = [
		"0001101", "0011001", "0010011", "0111101", "0100011",
		"0110001", "0101111", "0111011", "0110111", "0001011",
	];
	const EAN_G = [
		"0100111", "0110011", "0011011", "0100001", "0011101",
		"0111001", "0000101", "0010001", "0001001", "0010111",
	];
	const EAN_R = [
		"1110010", "1100110", "1101100", "1000010", "1011100",
		"1001110", "1010000", "1000100", "1001000", "1110100",
	];
	const EAN_PARITY = [
		"LLLLLL", "LLGLGG", "LLGGLG", "LLGGGL", "LGLLGG",
		"LGGLLG", "LGGGLL", "LGLGLG", "LGLGGL", "LGGLGL",
	];

	function ean13Svg(code) {
		const value = String(code || "");
		if (!/^\d{13}$/.test(value)) return "";
		const digits = value.split("").map(Number);
		const parity = EAN_PARITY[digits[0]];
		let bits = "101";
		for (let i = 1; i <= 6; i++) {
			bits += parity[i - 1] === "L" ? EAN_L[digits[i]] : EAN_G[digits[i]];
		}
		bits += "01010";
		for (let i = 7; i <= 12; i++) bits += EAN_R[digits[i]];
		bits += "101";

		const module = 2;
		const height = 52;
		let x = 8;
		let bars = "";
		for (const bit of bits) {
			if (bit === "1") {
				bars += `<rect x="${x}" y="0" width="${module}" height="${height}" fill="#000"/>`;
			}
			x += module;
		}
		const width = x + 8;
		return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height + 16}" viewBox="0 0 ${width} ${height + 16}">
			<rect width="100%" height="100%" fill="#fff"/>
			${bars}
			<text x="${width / 2}" y="${height + 13}" font-family="monospace" font-size="10" text-anchor="middle">${value}</text>
		</svg>`;
	}

	function print_item_label(item) {
		const esc = frappe.utils.escape_html;
		const barcode = String(item.barcode || item.custom_barcode || "").trim();
		const svg = ean13Svg(barcode);
		const html = `<!doctype html><html><head><meta charset="utf-8"><style>
			@page { size: 50mm 30mm; margin: 2mm; }
			body { font-family: Arial, "Segoe UI", sans-serif; margin: 0; padding: 2mm; text-align: center; }
			.name { font-size: 11px; font-weight: 700; line-height: 1.15; }
			.code { font-size: 9px; margin-top: 2px; }
			.barcode { margin-top: 3px; }
			.barcode svg { max-width: 46mm; height: auto; }
			@media print { body { width: 46mm; } }
		</style></head><body>
			<div class="name">${esc(item.item_name || item.item_code || "")}</div>
			<div class="code">${esc(item.item_code || "")}</div>
			${svg ? `<div class="barcode">${svg}</div>` : `<div class="code">${esc(barcode)}</div>`}
		</body></html>`;
		const win = window.open("", "_blank", "width=420,height=320");
		if (!win) {
			frappe.msgprint(__("Please allow pop-ups to print the label."));
			return;
		}
		win.document.write(html);
		win.document.close();
		win.addEventListener("load", () => win.print());
	}

	// ------------------------------------------------------------------
	// Add New Item dialog (DEC-100) - the Item list and the three documents
	// ------------------------------------------------------------------
	function selling_price_nos(selling) {
		const dozens = flt(selling);
		return dozens > 0 ? dozens / PCS_PER_DOZEN : 0;
	}

	function show_create_error(error) {
		const message = (error && (error.message || error._server_messages)) || String(error);
		frappe.msgprint({
			title: __("Could not create the item"),
			message: message,
			indicator: "red",
		});
	}

	// "Edit in full" hands the values typed in the dialog to the full Item form
	// (DEC-100). The handoff travels through localStorage so it also survives the
	// new tab the document dialogs open, and is consumed once in Item.onload.
	const ITEM_FORM_DEFAULTS_KEY = "diva_item_form_defaults";

	function item_form_defaults(values) {
		const opts = { stock_uom: "Dozen" };
		const text = (value) => String(value || "").trim();
		if (text(values.item_code)) opts.item_code = text(values.item_code);
		if (text(values.item_name)) opts.item_name = text(values.item_name);
		if (text(values.item_group)) opts.item_group = text(values.item_group);
		if (text(values.barcode)) opts.custom_barcode = text(values.barcode);
		if (flt(values.selling_price) > 0) opts.standard_rate = flt(values.selling_price);
		if (flt(values.buying_price) > 0) opts.custom_buying_price = flt(values.buying_price);
		if (flt(values.wholesale_price) > 0) opts.custom_wholesale_price = flt(values.wholesale_price);
		if (values.opening_stock !== undefined && values.opening_stock !== null) {
			opts.opening_stock = flt(values.opening_stock);
		}
		return opts;
	}

	function open_item_full_form(values, new_tab) {
		const opts = item_form_defaults(values);
		// Hand the values over through localStorage and apply them once in
		// Item.refresh, where the form fields already exist. This works for the
		// same-tab navigation and for the new tab the document dialogs open.
		try {
			window.localStorage.setItem(
				ITEM_FORM_DEFAULTS_KEY,
				JSON.stringify({ opts: opts, at: Date.now() })
			);
		} catch (error) {
			// Storage may be disabled; the full form still opens, just blank.
		}
		if (new_tab) {
			window.open("/desk/stock/item/new", "_blank");
		} else {
			frappe.set_route("Form", "Item", "new");
		}
	}

	// Opening stock mode (Item list): create the item and post the opening
	// stock through a submitted Stock Reconciliation.
	function open_item_dialog() {
		if (window._diva_item_dialog) {
			const existing = window._diva_item_dialog;
			existing.set_values({
				item_code: "",
				item_name: "",
				item_group: "Accessories",
				barcode: "",
				opening_stock: 1,
				warehouse: DEFAULT_WAREHOUSE,
				buying_price: 0,
				selling_price: 0,
				selling_price_nos: 0,
				wholesale_price: 0,
			});
			existing.show();
			return;
		}

		const dialog = new frappe.ui.Dialog({
			title: __("Add New Item"),
			size: "large",
			fields: [
				{ fieldtype: "Section Break", label: __("Item") },
				{ fieldname: "item_code", label: __("Item Code"), fieldtype: "Data", reqd: 1 },
				{ fieldname: "item_name", label: __("Item Name"), fieldtype: "Data", reqd: 1 },
				{
					fieldname: "item_group",
					label: __("Item Group"),
					fieldtype: "Link",
					options: "Item Group",
					reqd: 1,
					default: "Accessories",
				},
				{
					fieldname: "barcode",
					label: __("Barcode (EAN-13)"),
					fieldtype: "Data",
					description: __("Leave it blank to generate an internal EAN-13 (starts with 20)."),
				},
				{ fieldtype: "Column Break" },
				{
					fieldname: "buying_price",
					label: __("Buying Price (EGP/Dozen)"),
					fieldtype: "Currency",
					reqd: 1,
				},
				{
					fieldname: "selling_price",
					label: __("Selling Price (EGP/Dozen)"),
					fieldtype: "Currency",
					reqd: 1,
				},
				{
					fieldname: "selling_price_nos",
					label: __("Selling Price (EGP/Nos)"),
					fieldtype: "Currency",
					read_only: 1,
					description: __("One Dozen = 12 Nos; saved automatically."),
				},
				{
					fieldname: "wholesale_price",
					label: __("Wholesale Price (EGP/Dozen)"),
					fieldtype: "Currency",
					description: __("Optional. Written to the Wholesale price list."),
				},
				{ fieldtype: "Section Break", label: __("Opening stock") },
				{
					fieldname: "opening_stock",
					label: __("Opening Stock (Dozen)"),
					fieldtype: "Float",
					default: 1,
					reqd: 1,
				},
				{
					fieldname: "warehouse",
					label: __("Accepted Warehouse"),
					fieldtype: "Link",
					options: "Warehouse",
					reqd: 1,
					default: DEFAULT_WAREHOUSE,
				},
				{
					fieldtype: "HTML",
					options: `<div class="text-muted small">${__(
						"Opening stock is posted in Dozen at the buying price, using the company's Temporary Opening account."
					)}</div>`,
				},
			],
			primary_action_label: __("Create Item & Post Stock"),
			primary_action(values) {
				dialog.hide();
				frappe.dom.freeze(__("Creating the item..."));
				frappe
					.xcall("diva_guard.desk_api.create_item_with_opening_stock", {
						item_code: values.item_code,
						item_name: values.item_name,
						item_group: values.item_group,
						barcode: values.barcode || "",
						selling_price: values.selling_price,
						wholesale_price: values.wholesale_price || 0,
						buying_price: values.buying_price,
						accepted_qty: values.opening_stock,
						warehouse: values.warehouse,
						post_opening_stock: 1,
					})
					.then((result) => {
						frappe.show_alert({
							message: __("Item {0} created with opening stock", [result.item_code]),
							indicator: "green",
						});
						if (window.cur_list && typeof cur_list.refresh === "function") {
							cur_list.refresh();
						}
					})
					.catch(show_create_error)
					.finally(() => frappe.dom.unfreeze());
			},
			secondary_action_label: __("Edit in full"),
			secondary_action() {
				// Frappe binds this to the click event, so read the fields here.
				const values = {};
				dialog.fields.forEach((df) => {
					if (df.fieldname) values[df.fieldname] = dialog.get_value(df.fieldname);
				});
				dialog.hide();
				open_item_full_form(values, false);
			},
		});

		dialog.fields_dict.selling_price.$input.on("change", () => {
			dialog.set_value("selling_price_nos", selling_price_nos(dialog.get_value("selling_price")));
		});

		window._diva_item_dialog = dialog;
		dialog.show();
	}

	// Document mode (Purchase Receipt / Purchase Invoice / Sales Invoice): create
	// the item only, then add it as a line. The document moves the stock; no
	// opening Stock Reconciliation is posted, so nothing is counted twice.
	function add_new_item_dialog(frm) {
		if (!frm || !is_draft(frm)) return;
		const warehouse = frm.doc.set_warehouse || DEFAULT_WAREHOUSE;
		const is_sales = frm.doctype === "Sales Invoice";
		if (frm._diva_add_item_dialog) {
			const existing = frm._diva_add_item_dialog;
			existing.set_values({
				item_code: "",
				item_name: "",
				item_group: "Accessories",
				barcode: "",
				quantity: 1,
				buying_price: 0,
				selling_price: 0,
				selling_price_nos: 0,
				warehouse: frm.doc.set_warehouse || DEFAULT_WAREHOUSE,
				print_label: 1,
			});
			existing.show();
			return;
		}

		const dialog = new frappe.ui.Dialog({
			title: __("Add New Item"),
			size: "large",
			fields: [
				{ fieldtype: "Section Break", label: __("Item") },
				{ fieldname: "item_code", label: __("Item Code"), fieldtype: "Data", reqd: 1 },
				{ fieldname: "item_name", label: __("Item Name"), fieldtype: "Data", reqd: 1 },
				{
					fieldname: "item_group",
					label: __("Item Group"),
					fieldtype: "Link",
					options: "Item Group",
					reqd: 1,
					default: "Accessories",
				},
				{
					fieldname: "barcode",
					label: __("Barcode (EAN-13)"),
					fieldtype: "Data",
					description: __("Leave it blank to generate an internal EAN-13 (starts with 20)."),
				},
				{ fieldtype: "Column Break" },
				{
					fieldname: "buying_price",
					label: __("Buying Price (EGP/Dozen)"),
					fieldtype: "Currency",
					reqd: is_sales ? 0 : 1,
				},
				{
					fieldname: "selling_price",
					label: __("Selling Price (EGP/Dozen)"),
					fieldtype: "Currency",
					reqd: 1,
				},
				{
					fieldname: "selling_price_nos",
					label: __("Selling Price (EGP/Nos)"),
					fieldtype: "Currency",
					read_only: 1,
					description: __("One Dozen = 12 Nos; saved automatically."),
				},
				{ fieldtype: "Section Break", label: __("Document line") },
				{
					fieldname: "quantity",
					label: __("Quantity (Dozen)"),
					fieldtype: "Float",
					default: 1,
					reqd: 1,
				},
				{
					fieldname: "warehouse",
					label: __(is_sales ? "Source Warehouse" : "Accepted Warehouse"),
					fieldtype: "Link",
					options: "Warehouse",
					reqd: 0,
					default: warehouse,
				},
				{
					fieldname: "print_label",
					label: __("Print the label after saving"),
					fieldtype: "Check",
					default: 1,
				},
			],
			primary_action_label: __("Create Item & Add Line"),
			primary_action(values) {
				dialog.hide();
				frappe.dom.freeze(__("Creating the item..."));
				frappe
					.xcall("diva_guard.desk_api.create_item_with_opening_stock", {
						item_code: values.item_code,
						item_name: values.item_name,
						item_group: values.item_group,
						barcode: values.barcode || "",
						selling_price: values.selling_price,
						wholesale_price: 0,
						buying_price: values.buying_price || 0,
						accepted_qty: values.quantity,
						warehouse: values.warehouse || warehouse,
						post_opening_stock: 0,
					})
					.then((item) => {
						const rate = is_sales ? values.selling_price : values.buying_price || 0;
						const row = frm.add_child("items", {
							item_code: item.item_code,
							item_name: item.item_name,
							qty: values.quantity,
							uom: "Dozen",
							conversion_factor: PCS_PER_DOZEN,
							rate: rate,
						});
						if (values.warehouse) row.warehouse = values.warehouse;
						frm.refresh_field("items");
						if (values.print_label) print_item_label(item);
						frappe.show_alert({
							message: __("Item {0} added", [item.item_code]),
							indicator: "green",
						});
					})
					.catch(show_create_error)
					.finally(() => frappe.dom.unfreeze());
			},
			secondary_action_label: __("Edit in full"),
			secondary_action() {
				// Frappe binds this to the click event, so read the fields here; the
				// document stays open in this tab while the Item form opens in a new one.
				const values = {};
				dialog.fields.forEach((df) => {
					if (df.fieldname) values[df.fieldname] = dialog.get_value(df.fieldname);
				});
				dialog.hide();
				open_item_full_form(values, true);
			},
		});

		dialog.fields_dict.selling_price.$input.on("change", () => {
			dialog.set_value("selling_price_nos", selling_price_nos(dialog.get_value("selling_price")));
		});

		frm._diva_add_item_dialog = dialog;
		dialog.show();
	}

	function is_item_list_route() {
		const route = (frappe.get_route && frappe.get_route()) || [];
		const parts = route.map((part) => String(part).toLowerCase());
		return parts.includes("list") && parts.includes("item");
	}

	// The Item list "Add Item" opens the Diva dialog; a Link field's "+" on a
	// form still opens the standard quick entry (not on the list route).
	const original_new_doc = frappe.new_doc;
	frappe.new_doc = function (doctype, opts, init_callback) {
		if (doctype === "Item" && is_item_list_route()) {
			open_item_dialog();
			return Promise.resolve();
		}
		return original_new_doc.call(this, doctype, opts, init_callback);
	};

	// Apply the values handed over by "Edit in full" (DEC-100) once, on the new
	// Item form. The new-tab path reads localStorage (the same-tab path uses
	// frappe.route_options); a stale handoff older than two minutes is ignored.
	frappe.ui.form.on("Item", {
		refresh(frm) {
			if (!is_new(frm) || frm._diva_defaults_applied) return;
			let raw = null;
			try {
				raw = window.localStorage.getItem(ITEM_FORM_DEFAULTS_KEY);
			} catch (error) {
				raw = null;
			}
			if (!raw) return;
			try {
				window.localStorage.removeItem(ITEM_FORM_DEFAULTS_KEY);
			} catch (error) {
				// ignore: the worst case is the values appear twice.
			}
			let payload;
			try {
				payload = JSON.parse(raw);
			} catch (error) {
				return;
			}
			if (!payload || !payload.opts) return;
			if (payload.at && Date.now() - payload.at > 120000) return;
			frm._diva_defaults_applied = true;
			Object.keys(payload.opts).forEach((key) => {
				if (frm.fields_dict[key]) frm.set_value(key, payload.opts[key]);
			});
		},
	});

	// ------------------------------------------------------------------
	// Purchase Invoice / Payment Entry: Print + Share (submitted)
	// ------------------------------------------------------------------
	frappe.ui.form.on("Purchase Invoice", {
		refresh(frm) {
			if (is_draft(frm)) {
				frm.add_custom_button(__("Add New Item"), () => add_new_item_dialog(frm));
			}
			if (is_submitted(frm)) {
				add_share_buttons(frm, PURCHASE_INVOICE_PRINT_FORMAT);
			}
		},
	});

	frappe.ui.form.on("Payment Entry", {
		refresh(frm) {
			if (is_submitted(frm)) {
				add_share_buttons(frm, PAYMENT_RECEIPT_PRINT_FORMAT);
			}
		},
	});

	// ------------------------------------------------------------------
	// Purchase Receipt: Add New Item on drafts, Print on submits.
	// Save/Submit keep the ERPNext default primary action (one button).
	// ------------------------------------------------------------------
	frappe.ui.form.on("Purchase Receipt", {
		refresh(frm) {
			if (is_draft(frm)) {
				focus_field(frm, "supplier");
				frm.add_custom_button(__("Add New Item"), () => add_new_item_dialog(frm));
			}
			if (is_submitted(frm)) {
				frm.add_custom_button(__("Print"), () =>
					open_print("Purchase Receipt", frm.doc.name, RECEIPT_PRINT_FORMAT)
				);
			}
		},
	});

	// ------------------------------------------------------------------
	// Sales Invoice: Add New Item on drafts; Pay + Print/Share on submits.
	// ------------------------------------------------------------------
	function pay_invoice_dialog(frm) {
		if (!is_submitted(frm) || flt(frm.doc.outstanding_amount) <= 0) {
			frappe.show_alert({
				message: __("This invoice has nothing left to pay."),
				indicator: "orange",
			});
			return;
		}
		const outstanding = flt(frm.doc.outstanding_amount);
		const dialog = new frappe.ui.Dialog({
			title: __("Pay Invoice {0}", [frm.doc.name]),
			fields: [
				{
					fieldname: "pay_full",
					label: __("Pay the full outstanding amount"),
					fieldtype: "Check",
					default: 1,
				},
				{
					fieldname: "amount",
					label: __("Amount to pay"),
					fieldtype: "Currency",
					reqd: 1,
					default: outstanding,
				},
				{
					fieldname: "mode_of_payment",
					label: __("Mode of Payment"),
					fieldtype: "Link",
					options: "Mode of Payment",
					reqd: 1,
					default: DEFAULT_PAYMENT_MODE,
				},
				{ fieldname: "reference_no", label: __("Reference No"), fieldtype: "Data" },
				{
					fieldname: "reference_date",
					label: __("Payment Date"),
					fieldtype: "Date",
					default: frappe.datetime.get_today(),
				},
				{
					fieldtype: "HTML",
					options: `<div class="text-muted small">${__(
						"Nothing is posted until you press Pay. The payment is then reviewed by a human, as always."
					)}</div>`,
				},
			],
			primary_action_label: __("Pay"),
			primary_action(values) {
				const amount = flt(values.amount);
				if (amount <= 0 || amount > outstanding + 0.005) {
					frappe.msgprint(__("Enter an amount between 0 and {0}", [money(outstanding)]));
					return;
				}
				dialog.hide();
				frappe.dom.freeze(__("Creating the payment..."));
				frappe
					.xcall("diva_guard.desk_api.pay_invoice", {
						invoice_name: frm.doc.name,
						amount: amount,
						mode_of_payment: values.mode_of_payment,
						reference_no: values.reference_no || "",
						reference_date: values.reference_date || frappe.datetime.get_today(),
					})
					.then((result) => {
						frappe.show_alert({
							message: __("Payment {0} submitted.", [result.payment_entry]),
							indicator: "green",
						});
						frm.reload_doc();
					})
					.catch((error) => {
						frappe.msgprint({
							title: __("Payment failed"),
							message: (error && (error.message || error._server_messages)) || String(error),
							indicator: "red",
						});
					})
					.finally(() => frappe.dom.unfreeze());
			},
		});

		const syncAmountMode = () => {
			const full = Boolean(dialog.get_value("pay_full"));
			dialog.set_value("amount", full ? outstanding : flt(dialog.get_value("amount")) || outstanding);
			dialog.set_df_property("amount", "read_only", full ? 1 : 0);
			dialog.set_df_property(
				"amount",
				"description",
				full ? __("Full outstanding amount") : __("Partial payment")
			);
		};
		dialog.fields_dict.pay_full.$input.on("change", syncAmountMode);
		dialog.show();
		syncAmountMode();
		setTimeout(() => dialog.fields_dict.pay_full.$input.trigger("focus"), 150);
	}

	frappe.ui.form.on("Sales Invoice", {
		refresh(frm) {
			if (is_draft(frm)) {
				focus_field(frm, "customer");
				frm.add_custom_button(__("Add New Item"), () => add_new_item_dialog(frm));
			}
			if (is_submitted(frm)) {
				add_share_buttons(frm, INVOICE_PRINT_FORMAT);
				if (flt(frm.doc.outstanding_amount) > 0) {
					frm.add_custom_button(__("Pay"), () => pay_invoice_dialog(frm));
				}
			}
		},
	});

	// ------------------------------------------------------------------
	// Item form: Enter on Opening Stock / Selling Price / UOM never opens the
	// image upload; move to the next safe field instead.
	// ------------------------------------------------------------------
	const ITEM_SAFE_NEXT = {
		opening_stock: "standard_rate",
		standard_rate: "stock_uom",
		stock_uom: "description",
	};

	function handle_item_enter(event) {
		if (event.key !== "Enter" || event.ctrlKey || event.metaKey || event.altKey) return false;
		const frm = active_form();
		if (!frm || frm.doctype !== "Item") return false;
		const fieldname = fieldname_of(event.target);
		if (!fieldname || !Object.prototype.hasOwnProperty.call(ITEM_SAFE_NEXT, fieldname)) {
			return false;
		}
		event.preventDefault();
		event.stopPropagation();
		const next = ITEM_SAFE_NEXT[fieldname];
		const next_field = frm.fields_dict && frm.fields_dict[next];
		if (next_field && next_field.$input && next_field.$input.length && !next_field.df.hidden) {
			focus_field(frm, next);
		} else if (event.target && event.target.blur) {
			event.target.blur();
		}
		return true;
	}

	// ------------------------------------------------------------------
	// Keyboard shortcuts
	// ------------------------------------------------------------------
	function shortcut_help() {
		const rows = [
			["F1", __("Show these shortcuts")],
			["F2", __("Focus customer / supplier")],
			["F3", __("Add or focus the item row")],
			["F8", __("Pay the Sales Invoice")],
			["F9", __("Print the current document")],
			["Tab", __("Accept the first suggestion, then jump on")],
			["Ctrl+S", __("Save")],
			["Ctrl+Enter", __("Submit")],
			["Ctrl+K", __("Search items, parties and invoices")],
		];
		const html = `<table class="table table-sm">${rows
			.map(
				([key, label]) =>
					`<tr><td style="width:110px"><kbd>${key}</kbd></td><td>${label}</td></tr>`
			)
			.join("")}</table>`;
		frappe.msgprint({ title: __("Diva shortcuts"), message: html, wide: true });
	}

	// Tab accepts the first open Link suggestion instead of leaving the field.
	function select_first_link_suggestion(input) {
		if (!input.value || !input.value.trim()) return false;
		const list = input.closest ? input.closest(".awesomplete") : null;
		const ul = list && list.querySelector("ul[role='listbox']");
		if (!ul || ul.hasAttribute("hidden") || !ul.children.length) return false;
		const fire = (key, keyCode) =>
			input.dispatchEvent(
				new KeyboardEvent("keydown", {
					key: key,
					keyCode: keyCode,
					which: keyCode,
					bubbles: true,
					cancelable: true,
				})
			);
		fire("ArrowDown", 40);
		fire("Enter", 13);
		return true;
	}

	function tab_target(frm, fieldname) {
		if (!frm) return null;
		if (frm.doctype === "Purchase Receipt") {
			if (fieldname === "supplier") return () => focus_field(frm, "set_warehouse");
			if (fieldname === "set_warehouse") return () => focus_item_row(frm);
		}
		if (frm.doctype === "Sales Invoice" && fieldname === "customer") {
			return () => focus_item_row(frm);
		}
		return null;
	}

	function active_form() {
		return window.cur_frm && window.cur_frm.doc ? window.cur_frm : null;
	}

	// app_include_js loads this on every Desk page; only the owner documents
	// get the Tab order and the save/submit keys.
	function is_desk_form(frm) {
		return Boolean(frm && (frm.doctype === "Purchase Receipt" || frm.doctype === "Sales Invoice"));
	}

	function dialog_is_open() {
		return $(".modal:visible").length > 0;
	}

	document.addEventListener(
		"keydown",
		(event) => {
			if (handle_item_enter(event)) return;

			const input = event.target;
			if (event.key === "Tab" && input && input.tagName === "INPUT") {
				const frm = active_form();
				const desk_form = is_desk_form(frm);
				if (!desk_form || dialog_is_open()) return;
				const fieldname = fieldname_of(input);
				const jump = tab_target(frm, fieldname);
				// Supplier -> warehouse -> items and Customer -> items always jump.
				// Any other Link field accepts the first suggestion when it has text.
				if (jump) {
					event.preventDefault();
					jump();
					return;
				}
				if (select_first_link_suggestion(input)) {
					event.preventDefault();
				}
			}

			if (event.key === "F1") {
				event.preventDefault();
				shortcut_help();
				return;
			}

			const frm = active_form();
			if (!frm || dialog_is_open() || !is_desk_form(frm)) return;
			const isSalesInvoice = frm.doctype === "Sales Invoice";
			const isPurchaseReceipt = frm.doctype === "Purchase Receipt";

			if (event.key === "F2") {
				event.preventDefault();
				if (isPurchaseReceipt) focus_field(frm, "supplier");
				else if (isSalesInvoice) focus_field(frm, "customer");
			} else if (event.key === "F3") {
				event.preventDefault();
				focus_item_row(frm);
			} else if (event.key === "F8" && isSalesInvoice) {
				event.preventDefault();
				pay_invoice_dialog(frm);
			} else if (event.key === "F9" && is_submitted(frm)) {
				event.preventDefault();
				if (isSalesInvoice) open_print("Sales Invoice", frm.doc.name, INVOICE_PRINT_FORMAT);
				else if (isPurchaseReceipt) {
					open_print("Purchase Receipt", frm.doc.name, RECEIPT_PRINT_FORMAT);
				}
			} else if (event.key.toLowerCase() === "s" && (event.ctrlKey || event.metaKey)) {
				if (!is_draft(frm)) return;
				event.preventDefault();
				frm.save();
			} else if (event.key === "Enter" && (event.ctrlKey || event.metaKey)) {
				if (!is_draft(frm)) return;
				event.preventDefault();
				frm.save("Submit");
			}
		},
		true
	);

	// ------------------------------------------------------------------
	// Item list: Left stock column and the primary barcode (DEC-96)
	// ------------------------------------------------------------------
	function enrich_item_list(listview) {
		if (!listview || listview.doctype !== "Item" || listview.view !== "List") return;
		if (listview._diva_stock_loading) return;
		const names = (listview.data || []).map((row) => row.name);
		if (!names.length) return;
		listview._diva_stock_loading = true;
		frappe
			.xcall("diva_guard.item_list.left_stock", { items: names })
			.then((totals) => {
				(listview.data || []).forEach((row) => {
					row.left_stock = (totals && totals[row.name]) || 0;
				});
				listview.render_list();
			})
			.finally(() => {
				listview._diva_stock_loading = false;
			});
	}

	function patch_item_list(listview) {
		if (
			!listview ||
			listview.doctype !== "Item" ||
			listview.view !== "List" ||
			listview._diva_patched
		) {
			return;
		}
		listview._diva_patched = true;
		listview.columns = (listview.columns || []).filter(
			(column) => !(column.df && column.df.fieldname === "opening_stock")
		);
		if (!(listview.columns || []).some((column) => column.df && column.df.fieldname === "left_stock")) {
			listview.columns.push({
				type: "Field",
				df: { fieldname: "left_stock", label: __("Left stock"), fieldtype: "Float" },
			});
		}
		if (listview.header) listview.render_header(true);
		const original_refresh = listview.refresh.bind(listview);
		listview.refresh = function (...args) {
			const result = original_refresh(...args);
			if (result && typeof result.then === "function") {
				result.then(() => enrich_item_list(listview));
			} else {
				setTimeout(() => enrich_item_list(listview), 800);
			}
			return result;
		};
		enrich_item_list(listview);
	}

	setInterval(() => {
		if (window.cur_list) patch_item_list(window.cur_list);
	}, 1000);

})();
